package com.tuya.passport.cloud.l4.service;

import com.tuya.passport.cloud.common.support.ApiException;
import com.tuya.passport.cloud.common.support.Hashing;
import com.tuya.passport.cloud.l3.service.SubjectSnapshotService;
import com.tuya.passport.cloud.l4.domain.*;
import com.tuya.passport.cloud.l4.repository.*;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service public class ReviewService {
 private final ReviewTaskRepository reviews;private final PublicationCandidateRepository candidates;private final ValidationRunRepository runs;private final ValidationService validation;private final FieldDefinitionService definitions;private final SubjectSnapshotService snapshots;private final Hashing hashing;
 public ReviewService(ReviewTaskRepository reviews,PublicationCandidateRepository candidates,ValidationRunRepository runs,ValidationService validation,FieldDefinitionService definitions,SubjectSnapshotService snapshots,Hashing hashing){this.reviews=reviews;this.candidates=candidates;this.runs=runs;this.validation=validation;this.definitions=definitions;this.snapshots=snapshots;this.hashing=hashing;}
 @Transactional public ReviewTaskEntity submit(String org,String actor,String type,String subjectId){ValidationService.ValidationResult result=validation.validate(org,type,subjectId);if("FAIL".equals(result.status()))throw ApiException.conflict("GOV_VALIDATION_FAILED","Validation found blocking issues");return reviews.findFirstByOrgCodeAndSubjectTypeAndSubjectIdAndSnapshotHashAndStatus(org,type,subjectId,result.inputHash(),ReviewStatus.PENDING_REVIEW).orElseGet(()->reviews.save(new ReviewTaskEntity(org,type,subjectId,result.inputHash(),actor)));}
 @Transactional public ReviewTaskEntity decide(String org,String checker,String id,String decision,String reason){ReviewTaskEntity task=reviews.findByOrgCodeAndId(org,id).orElseThrow(()->ApiException.notFound("GOV_NOT_FOUND","Review task not found"));if(task.getStatus()!=ReviewStatus.PENDING_REVIEW)throw ApiException.conflict("GOV_NOT_PENDING","Review task is no longer pending");if(task.getMakerId().equals(checker))throw ApiException.conflict("GOV_MAKER_CHECKER_CONFLICT","The maker cannot check their own submission");if(reason==null||reason.isBlank())throw ApiException.badRequest("GOV_VALIDATION_ERROR","A decision reason is required");boolean approve="APPROVE".equals(decision);if(!approve&& !"REQUEST_CHANGES".equals(decision))throw ApiException.badRequest("GOV_VALIDATION_ERROR","Decision must be APPROVE or REQUEST_CHANGES");
  if(approve){String actual=snapshots.currentHash(org,task.getSubjectType(),task.getSubjectId());if(!actual.equals(task.getSnapshotHash()))throw ApiException.conflict("GOV_SNAPSHOT_STALE","Subject data changed after review was submitted");ValidationRunEntity latest=runs.findByOrgCodeOrderByFinishedAtDesc(org).stream().filter(r->r.getSubjectType().equals(task.getSubjectType())&&r.getSubjectId().equals(task.getSubjectId())&&r.getInputHash().equals(task.getSnapshotHash())).findFirst().orElseThrow(()->ApiException.conflict("GOV_VALIDATION_FAILED","Matching validation run not found"));Map<String,Object> snap=snapshots.snapshot(org,task.getSubjectType(),task.getSubjectId());Map<String,Object> flat=validation.fields(snap);mergeDppAttributes(flat,snap);List<FieldDefinitionEntity> defs=definitions.ensureDefaults(org);Map<String,Object> pub=new LinkedHashMap<>(),restricted=new LinkedHashMap<>(),regulator=new LinkedHashMap<>();for(FieldDefinitionEntity def:defs){String code=def.getFieldCode();String camel=camel(code);Object value=flat.get(camel);if(value==null)value=flat.get(code);if(value==null){String alias=switch(code){case "battery_model_identifier"->"modelCode";case "battery_serial_number"->"snRaw";case "manufacturing_date"->"manufacturedAt";case "manufacturer_information"->"manufacturerName";case "materials_battery_chemistry"->"chemistryCode";case "performance_nominal_voltage"->"ratedVoltageV";default->null;};if(alias!=null)value=flat.get(alias);}if(value==null)continue;switch(def.getVisibilityClass()){case PUBLIC->{pub.put(code,value);if(aliasLegacy(code)!=null)pub.put(aliasLegacy(code),value);}case RESTRICTED->restricted.put(code,value);case REGULATOR->regulator.put(code,value);case INTERNAL->{}}}
   PublicationCandidateEntity candidate=candidates.findByOrgCodeAndSubjectTypeAndSubjectIdOrderByCreatedAtDesc(org,task.getSubjectType(),task.getSubjectId()).stream().filter(x->x.getSnapshotHash().equals(task.getSnapshotHash())).findFirst().orElseGet(()->candidates.save(new PublicationCandidateEntity(org,task.getSubjectType(),task.getSubjectId(),task.getSnapshotHash(),hashing.json(pub),hashing.json(restricted),hashing.json(regulator),latest.getId(),task.getId())));if(candidate.getStatus()!=CandidateStatus.READY&&candidate.getStatus()!=CandidateStatus.CONSUMED)throw ApiException.conflict("GOV_CANDIDATE_STALE","Publication candidate is stale");}
  task.decide(checker,reason,approve);return reviews.save(task);
 }
 @Transactional(readOnly=true) public PublicationCandidateEntity readyCandidate(String org,String type,String subject){return candidates.findFirstByOrgCodeAndSubjectTypeAndSubjectIdAndStatusOrderByCreatedAtDesc(org,type,subject,CandidateStatus.READY).orElseThrow(()->ApiException.notFound("GOV_CANDIDATE_NOT_FOUND","No ready publication candidate found"));}
 private static void mergeDppAttributes(Map<String,Object> flat,Map<String,Object> snapshot){for(String section:List.of("revision","unit")){Object raw=snapshot.get(section);if(raw instanceof Map<?,?> map){Object json=map.get("attributeJson");if(json instanceof String s&&!s.isBlank())try{Map<?,?> attrs=new com.fasterxml.jackson.databind.ObjectMapper().readValue(s,Map.class);Object dpp=attrs.get("dpp");if(dpp instanceof Map<?,?> values)values.forEach((k,v)->flat.put(String.valueOf(k),v));Object snDerived=attrs.get("snDerived");if(snDerived instanceof Map<?,?> values)values.forEach((k,v)->flat.putIfAbsent(String.valueOf(k),v));}catch(Exception ignored){}}}}
 private static String aliasLegacy(String code){return switch(code){case "battery_model_identifier"->"model_code";case "battery_serial_number"->"sn";case "manufacturing_date"->"manufactured_at";case "manufacturer_information"->"manufacturer_name";case "materials_battery_chemistry"->"chemistry";case "performance_nominal_voltage"->"rated_voltage_v";case "battery_mass"->"battery_mass";default->null;};}
 private static String camel(String snake){StringBuilder b=new StringBuilder();boolean upper=false;for(char c:snake.toCharArray()){if(c=='_')upper=true;else{b.append(upper?Character.toUpperCase(c):c);upper=false;}}return b.toString();}
}
